from docx import Document
from docx.oxml.ns import qn
doc = Document('/root/offer_letter_template.docx')

# Check table cells more thoroughly - look at raw XML
for ti, table in enumerate(doc.tables):
    for ri, row in enumerate(table.rows):
        for ci, cell in enumerate(row.cells):
            # Check for nested tables
            nested = cell._tc.findall(qn('w:tbl'))
            if nested:
                print(f'Table {ti} [{ri},{ci}] has {len(nested)} nested table(s)')
            for pi, p in enumerate(cell.paragraphs):
                if p.text.strip():
                    print(f'Table {ti} [{ri},{ci}] para {pi}: {p.text!r}')
                    for runi, run in enumerate(p.runs):
                        print(f'  run {runi}: {run.text!r} bold={run.bold}')

# Also check for nested tables within cells
print('\n=== Checking nested tables ===')
for ti, table in enumerate(doc.tables):
    for ri, row in enumerate(table.rows):
        for ci, cell in enumerate(row.cells):
            for nested_table in cell.tables:
                for nri, nrow in enumerate(nested_table.rows):
                    for nci, ncell in enumerate(nrow.cells):
                        for pi, p in enumerate(ncell.paragraphs):
                            if p.text.strip():
                                print(f'Nested [{nri},{nci}] para {pi}: {p.text!r}')
                                for runi, run in enumerate(p.runs):
                                    print(f'  run {runi}: {run.text!r} bold={run.bold}')
