from docx import Document
doc = Document('/root/offer_letter_filled.docx')

# Check all text for leftover placeholders
issues = []
for i, p in enumerate(doc.paragraphs):
    if '{{' in p.text:
        issues.append(f'Paragraph {i}: {p.text}')

def check_tables(tables):
    for table in tables:
        for row in table.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    if '{{' in p.text:
                        issues.append(f'Table cell: {p.text}')
                check_tables(cell.tables)

check_tables(doc.tables)

if issues:
    print('LEFTOVER PLACEHOLDERS FOUND:')
    for i in issues:
        print(f'  {i}')
else:
    print('No leftover placeholders. Document is clean.')
"
